package main

import (
	"context"
	"errors"
	"fmt"
	"os"
	"os/exec"
	"strings"
	"time"
)

// child is what this same program does when started with a role argument.
func child(role string, args []string) {
	switch role {
	case "echo":
		for i, a := range args {
			fmt.Printf("  arg %d: %q\n", i+1, a)
		}
	case "fail":
		fmt.Fprintln(os.Stderr, "config.toml: no such file")
		os.Exit(3)
	case "hang":
		time.Sleep(time.Hour)
	}
}

func main() {
	if len(os.Args) > 1 {
		child(os.Args[1], os.Args[2:])
		return
	}
	ctx := context.Background()

	// A real tool, looked up on PATH, run directly: no shell in between.
	out, err := exec.CommandContext(ctx, "go", "list", "-f", "{{.Doc}}", "os/exec").Output()
	fmt.Printf("go list: %q err=%v\n", strings.TrimSpace(string(out)), err)

	self, err := os.Executable()
	if err != nil {
		panic(err)
	}
	fmt.Println("user input as arguments:")
	out, _ = exec.CommandContext(ctx, self, "echo", "Ayşe Yılmaz", "x; rm -rf ~", "$(whoami)", "*.go").Output()
	fmt.Print(string(out))

	_, err = exec.CommandContext(ctx, self, "fail").Output()
	if ee, ok := errors.AsType[*exec.ExitError](err); ok {
		fmt.Printf("failing child: exit code %d, stderr %q\n", ee.ExitCode(), ee.Stderr)
	}

	tctx, cancel := context.WithTimeout(ctx, 300*time.Millisecond)
	defer cancel()
	cmd := exec.CommandContext(tctx, self, "hang")
	cmd.WaitDelay = time.Second // after the kill, don't wait forever for its pipes
	err = cmd.Run()
	fmt.Println("hanging child: killed at the deadline:", err != nil && errors.Is(tctx.Err(), context.DeadlineExceeded))
}

files.examples/03_reverse_proxy.go:
package main

import (
	"fmt"
	"io"
	"log"
	"net/http"
	"net/http/httptest"
	"net/http/httputil"
	"net/url"
	"time"
)

func main() {
	backend := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		fmt.Fprintf(w, "backend: %s %s\n", r.Method, r.URL.Path)
		fmt.Fprintf(w, "  X-Forwarded-For: %q\n", r.Header.Get("X-Forwarded-For"))
		fmt.Fprintf(w, "  X-Gateway:       %q\n", r.Header.Get("X-Gateway"))
	}))
	target, err := url.Parse(backend.URL + "/api")
	if err != nil {
		log.Fatal(err)
	}

	proxy := &httputil.ReverseProxy{
		Rewrite: func(pr *httputil.ProxyRequest) {
			pr.SetURL(target)                        // /orders/42 -> /api/orders/42
			pr.SetXForwarded()                       // the client's real address
			pr.Out.Header.Set("X-Gateway", "edge-1") // the backend may trust this
		},
		ModifyResponse: func(resp *http.Response) error {
			resp.Header.Set("Cache-Control", "no-store")
			return nil
		},
		ErrorHandler: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, "upstream unavailable", http.StatusBadGateway) // log err, don't show it
		},
	}
	front := httptest.NewServer(proxy)
	defer front.Close()

	client := &http.Client{Timeout: 5 * time.Second}
	call := func() {
		req, _ := http.NewRequest(http.MethodGet, front.URL+"/orders/42", nil)
		req.Header.Set("X-Forwarded-For", "203.0.113.7") // a client trying to look like someone else
		req.Header.Set("Connection", "X-Gateway")        // ...and to get our header stripped
		resp, err := client.Do(req)
		if err != nil {
			log.Fatal(err)
		}
		defer resp.Body.Close()
		body, _ := io.ReadAll(resp.Body)
		fmt.Printf("%d Cache-Control=%q\n%s", resp.StatusCode, resp.Header.Get("Cache-Control"), body)
	}
	call()
	backend.Close() // the backend goes away
	call()
}
